// Bundles the interface code (assets/js/app.js and its modules) into assets/js/app.bundle.js,
// so phones download one file instead of a chain of ~45. The data files stay separate: the
// automatic updates rewrite them without rebuilding the bundle.
// The stylesheets are joined the same way into assets/css/app.css (one file instead of seven).
// Usage: node scripts/build-bundle.mjs          (writes the bundle)
//        node scripts/build-bundle.mjs --check  (fails if the bundle is out of date)
// Needs esbuild: npm install --no-save --no-package-lock esbuild@0.25.5
import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
const require = createRequire(import.meta.url);
const esbuild = require('esbuild');

export const dataModules = ['fighter-directory-data.js', 'fighter-stance-data.js', 'fighter-martial-data.js', 'fighter-info-data.js', 'official-events.js'];
const root = new URL('../assets/js/', import.meta.url);
const target = new URL('app.bundle.js', root);

const result = await esbuild.build({
  entryPoints: [new URL('app.js', root).pathname],
  bundle: true, format: 'esm', target: 'es2022', minify: true, legalComments: 'none', write: false, logLevel: 'error',
  // Keep data modules as separate files, imported from the bundle's own folder.
  plugins: [{ name: 'external-data', setup(build) {
    // Translations load on demand (only for English and Catalan), so they stay out of the bundle.
    build.onResolve({ filter: /\/i18n\/dictionaries\.js$/ }, () => ({ path: './i18n/dictionaries.js', external: true }));
    build.onResolve({ filter: new RegExp(`/(${dataModules.join('|').replaceAll('.', '\\.')})$`) },
      args => ({ path: './' + args.path.split('/').pop(), external: true }));
  } }],
});
const output = '// Generated by scripts/build-bundle.mjs from assets/js/app.js. Do not edit.\n' + result.outputFiles[0].text;

// Stylesheets, in the order index.html used to load them (later files refine earlier ones).
export const stylesheets = ['fonts.css', 'main.css', 'mobile.css', 'refinement.css', 'pickem.css', 'editorial.css', 'adsense.css'];
const cssRoot = new URL('../assets/css/', import.meta.url);
const cssTarget = new URL('app.css', cssRoot);
const joined = stylesheets.map(name => readFileSync(new URL(name, cssRoot), 'utf8')).join('\n');
const css = (await esbuild.transform(joined, { loader: 'css', minify: true, legalComments: 'none' })).code;
const cssOutput = '/* Generated by scripts/build-bundle.mjs from ' + stylesheets.join(', ') + '. Do not edit. */\n' + css;

if (process.argv.includes('--check')) {
  const read = url => { try { return readFileSync(url, 'utf8'); } catch { return ''; } };
  if (read(target) !== output) { console.error('assets/js/app.bundle.js está desactualizado: ejecuta node scripts/build-bundle.mjs'); process.exit(1); }
  if (read(cssTarget) !== cssOutput) { console.error('assets/css/app.css está desactualizado: ejecuta node scripts/build-bundle.mjs'); process.exit(1); }
  console.log(`PASS: paquete de la interfaz al día (${Math.round(output.length / 1024)} KB) y estilos al día (${Math.round(cssOutput.length / 1024)} KB)`);
} else {
  writeFileSync(target, output);
  writeFileSync(cssTarget, cssOutput);
  console.log(`Paquete de la interfaz: ${Math.round(output.length / 1024)} KB; estilos: ${Math.round(cssOutput.length / 1024)} KB; datos aparte: ${dataModules.join(', ')}`);
}
